create table if not exists public.site_service_cards(id uuid primary key default gen_random_uuid(),card_key text not null unique check(card_key in('vehicles','properties','packages','b2b')),eyebrow text not null default '',title text not null,description text not null default '',features jsonb not null default '[]'::jsonb check(jsonb_typeof(features)='array'),image_url text,storage_path text,primary_label text not null default 'Explore',primary_url text not null default '/',secondary_label text not null default '',secondary_url text not null default '',sort_order integer not null default 0,is_active boolean not null default true,updated_at timestamptz not null default now());
alter table public.site_service_cards enable row level security;
grant select on public.site_service_cards to anon,authenticated;
grant insert,update,delete on public.site_service_cards to authenticated;
create policy "Public reads published service cards" on public.site_service_cards for select to anon,authenticated using(is_active or auth.uid()='79482db3-a3f7-4773-bb8d-5a79c9d10237'::uuid);
create policy "Admin manages service cards" on public.site_service_cards for all to authenticated using(auth.uid()='79482db3-a3f7-4773-bb8d-5a79c9d10237'::uuid) with check(auth.uid()='79482db3-a3f7-4773-bb8d-5a79c9d10237'::uuid);
insert into public.site_service_cards(card_key,eyebrow,title,description,features,primary_label,primary_url,secondary_label,secondary_url,sort_order) values
('vehicles','01 · FOR TRAVELLERS','Explore Himalayan Travel','Discover curated mountain journeys and trusted local travel services, supported by our Narkanda-based team.','["Private cabs and vehicle options","Hotels, homestays and mountain stays","Group tours and custom itineraries"]','Build Your Trip','/build-your-trip/','View Trips','/packages/',1),
('properties','02 · LOCAL SERVICE PARTNERS','List a Cab, Hotel or Property','Are you a driver, cab operator, hotelier or homestay owner? Submit your details to join our private partner network and receive relevant enquiries.','["Register cabs and commercial vehicles","List hotels, homestays and properties","Your contact details stay private"]','List Your Service','/suppliers/','View Marketplace','/marketplace/',2),
('packages','03 · TOUR PACKAGES','Discover Himalayan Tour Packages','Explore curated journeys across Spiti, Kinnaur and Himachal, with group departures and private itineraries.','["Spiti, Kinnaur and Himachal journeys","Group departures and private itineraries","Custom routes and travel support"]','View Packages','/packages/','Build Your Trip','/build-your-trip/',3),
('b2b','04 · B2B PARTNERSHIPS','Offer Services to Travel Businesses','Connect with us for business-to-business travel requirements, ground support and destination services.','["Local guides, experiences and activities","Restaurants, catering and event support","Equipment, logistics and destination services"]','Offer a B2B Service','https://wa.me/919816929669','Enquire for B2B Rates','https://wa.me/919816929669',4) on conflict(card_key) do nothing;